use std::{fs,path::Path,collections::BTreeMap};
fn main(){let arg=std::env::args().nth(1).unwrap();let p=Path::new(&arg);let raw=fs::read_to_string(p.join("CONTROL.tsv")).unwrap();let cert=fs::read_to_string(p.join("CERT-CONTROL.tsv")).unwrap();let mut groups:BTreeMap<(usize,usize),(usize,usize,usize,usize,usize,usize,usize)>=BTreeMap::new();let(mut total,mut yes,mut missing,mut full,mut unobs,mut newyes)=(0,0,0,0,0,0);let prior=fs::read_to_string("research/hec_anchor_collision_20261116/SHIFT-CONTROL.tsv").unwrap();let mut old_reproduced=0;
for(a,b)in raw.lines().skip(1).zip(cert.lines().skip(1)){let x:Vec<_>=a.split('\t').collect();let y:Vec<_>=b.split('\t').collect();assert_eq!(x,y[..24]);let n=|j:usize|x[j].parse::<usize>().unwrap();total+=1;let success=x[8]=="verified";yes+=usize::from(success);newyes+=usize::from(success&&n(2)==1);missing+=usize::from(x[8]=="missing_input_row");full+=usize::from(success&&n(10)==n(11));let r:usize=y[24].parse().unwrap();let dr:usize=y[25].parse().unwrap();let ar:usize=y[26].parse().unwrap();assert_eq!(r,ar);assert_eq!(r-dr,usize::from(success));unobs+=usize::from(r==dr);let z=groups.entry((n(0),n(7))).or_insert((0,0,0,0,usize::MAX,0,0));z.0+=1;z.1+=usize::from(success);z.2+=usize::from(x[8]=="missing_input_row");z.3+=usize::from(r==dr);if success{z.4=z.4.min(n(18));z.5=z.5.max(n(18));z.6+=usize::from(n(10)==n(11));}
if n(2)==0&&n(5)==3{let old=prior.lines().skip(1).map(|l|l.split('\t').collect::<Vec<_>>()).find(|v|v[0]==x[0]&&v[1]==x[1]&&v[2]==x[4]).unwrap();for(i,j)in[(3,8),(4,9),(5,12),(8,14),(9,15),(10,16),(11,17),(12,18),(13,19),(14,20),(15,21),(16,22),(17,23),(22,13)]{assert_eq!(old[i],x[j]);}old_reproduced+=1;}}
assert_eq!(total,48);assert_eq!(fs::read(p.join("BASELINE.tsv")).unwrap(),fs::read(p.join("CERT-BASELINE.tsv")).unwrap());assert_eq!(fs::read(p.join("INPUTS.txt")).unwrap(),fs::read(p.join("CERT-INPUTS.txt")).unwrap());let bas=fs::read_to_string(p.join("BASELINE.tsv")).unwrap();let controls=bas.lines().skip(1).filter(|l|l.split('\t').nth(5).unwrap().starts_with("Some(")).count();let mut out=String::from("g\tH\tpolicies\tverified\tmissing_input_row\tunobservable\tverified_prepared_min\tverified_prepared_max\tverified_full_core_rank\n");for(&(g,h),&(n,v,m,u,lo,hi,fr))in&groups{let low=if v==0{"NA".into()}else{lo.to_string()};let high=if v==0{"NA".into()}else{hi.to_string()};out+=&format!("{g}\t{h}\t{n}\t{v}\t{m}\t{u}\t{low}\t{high}\t{fr}\n");}print!("{out}");fs::write(p.join("SUMMARY.tsv"),out).unwrap();let totals=format!("policies={total}\nverified={yes}\nmissing_input_row={missing}\nbounded_no_k={}\nunobservable={unobs}\nverified_full_core_rank={full}\nfull_degree_role_verified={newyes}\ncompact_control_verified={controls}\nprior_role0_size_rule_count_vectors_reproduced={old_reproduced}\nreplay_first24fields_equal=true\nreplay_control_and_input_bytes_equal=true\n",total-yes-missing);print!("{totals}");fs::write(p.join("TOTALS.txt"),totals).unwrap();
let mut svg=String::from("<svg xmlns='http://www.w3.org/2000/svg' width='1050' height='510'><rect width='1050' height='510' fill='white'/><g font-family='Arial' fill='#183845'><text x='35' y='35' font-size='22'>Smaller joint cores: verified source/target cases</text><text x='35' y='63' font-size='14'>Four cases per H: two public sources × two unchanged targets. All 32 failures have unobservable k.</text>");for(panel,g)in[2usize,3,4].iter().enumerate(){let vals:Vec<_>=groups.iter().filter(|(k,_)|k.0==*g).collect();let ox=65.+panel as f64*335.;svg+=&format!("<text x='{ox}' y='110' font-size='18'>Genus {g}</text><path d='M {ox} 365 h 280' stroke='#526673'/>");for(j,(key,val))in vals.iter().enumerate(){let x=ox+15.+j as f64*65.;let ht=val.1 as f64*55.;svg+=&format!("<rect x='{x}' y='{:.2}' width='36' height='{ht:.2}' fill='#287f82'/><text x='{x}' y='{:.2}' font-size='15'>{}/4</text><text x='{x}' y='392' font-size='14'>{}</text>",365.-ht,355.-ht,val.1,key.1);}svg+=&format!("<text x='{ox}' y='421' font-size='14'>H: anchor core size</text>");}svg+="<text x='35' y='464' font-size='14'>Every success has full core rank H+2; smaller matrices alone do not establish a total speedup.</text><text x='35' y='491' font-size='13'>hec_collision_core_20261116 / frozen count screen and rank replay / no timing or population estimate.</text></g></svg>";fs::write(p.join("COUNTS.svg"),svg).unwrap();}
